WITH enriched AS (SELECT *, LEAD(duration_sec, 1, 0) OVER (PARTITION BY session_id, page ORDER BY event_time, id) AS next_duration_sec, SUM(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec, LAST_VALUE(duration_sec) IGNORE NULLS OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_duration_sec FROM web_events) SELECT id, event_type, page, event_time, duration_sec, next_duration_sec, running_duration_sec FROM enriched ORDER BY duration_sec;
